package org.efootballrevival.runtimeprobe;
import fi.iki.elonen.NanoHTTPD;import fi.iki.elonen.NanoHTTPD.*;import java.io.*;import java.util.*;import org.json.*;
public final class LiveResourceServer{
 private static final Object LOCK=new Object();private static final LinkedList<Event> EVENTS=new LinkedList<>();private static long nextId;
 private static final class Event{final File root;final JSONObject row=new JSONObject();final long start=System.nanoTime();volatile long bytes;long expected,lastWrite;boolean closed;Event(File root,String method,String path,String range){this.root=root;try{row.put("id",++nextId).put("method",method).put("file",path).put("range",range==null?"":range).put("started_unix_ms",System.currentTimeMillis()).put("state","OPEN");}catch(JSONException ignored){}}}
 private static void flush(Event e,String state){synchronized(LOCK){try{e.row.put("state",state).put("server_bytes_read",e.bytes).put("elapsed_ms",(System.nanoTime()-e.start)/1000000);JSONArray rows=new JSONArray();for(Event x:EVENTS)rows.put(x.row);JSONObject doc=new JSONObject().put("version","73-ui7.4").put("note","Server stream reads; not proof of client resource mounting").put("requests",rows);File file=new File(e.root,"work/tools/http-resource-status.json"),temp=new File(file.getParentFile(),"http-resource-status.tmp");try(FileOutputStream out=new FileOutputStream(temp)){out.write(doc.toString(2).getBytes("UTF-8"));}if(!temp.renameTo(file))temp.delete();e.lastWrite=System.nanoTime();}catch(Exception ignored){}}}
 private static Event begin(File root,Method method,String path,String range){synchronized(LOCK){Event e=new Event(root,method.name(),path,range);EVENTS.addFirst(e);while(EVENTS.size()>32)EVENTS.removeLast();return e;}}
 private static Response response(Event e,Method method,Response.Status status,long total,long offset,long length,InputStream stream,String etag,String contentRange){synchronized(LOCK){try{e.expected=method==Method.HEAD?0:length;e.row.put("status",status.getRequestStatus()).put("file_bytes",total).put("offset",offset).put("expected_body_bytes",e.expected);}catch(JSONException ignored){}}Response out=NanoHTTPD.newFixedLengthResponse(status,"application/octet-stream",stream,length);out.setRequestMethod(method);out.addHeader("Accept-Ranges","bytes");out.addHeader("Cache-Control","no-cache");if(etag!=null)out.addHeader("ETag",etag);if(contentRange!=null)out.addHeader("Content-Range",contentRange);flush(e,method==Method.HEAD?"HEAD":length==0?"NO_BODY":"STREAM_OPEN");return out;}
 private static InputStream empty(){return new ByteArrayInputStream(new byte[0]);}
 private static final class Transfer extends FilterInputStream{final Event event;long remaining;Transfer(InputStream in,Event e,long n){super(in);event=e;remaining=n;}
  private void count(int n){if(n>0){remaining-=n;event.bytes+=n;if(System.nanoTime()-event.lastWrite>1000000000L)flush(event,"STREAMING");}}
  public int read()throws IOException{if(remaining<=0)return-1;int v=in.read();if(v>=0)count(1);return v;}
  public int read(byte[] b,int off,int len)throws IOException{if(len==0)return 0;if(remaining<=0)return-1;int n=in.read(b,off,(int)Math.min(remaining,len));count(n);return n;}
  public void close()throws IOException{try{super.close();}finally{synchronized(LOCK){if(!event.closed){event.closed=true;flush(event,event.bytes==event.expected?"SERVER_READ_COMPLETE":"STREAM_CLOSED_EARLY");}}}}
 }
 public static Response serve(File root,IHTTPSession session){Method method=session.getMethod();String uri=session.getUri(),name=uri.startsWith("/livedata/")?uri.substring(10):"",range=session.getHeaders().get("range");Event event=begin(root,method,name,range);
  try{
   File live=new File(root,"livedata").getCanonicalFile(),file=new File(live,name).getCanonicalFile();if(!file.getPath().startsWith(live.getPath()+File.separator))return response(event,method,Response.Status.FORBIDDEN,0,0,0,empty(),null,null);
   if(method!=Method.GET&&method!=Method.HEAD){Response r=response(event,method,Response.Status.METHOD_NOT_ALLOWED,0,0,0,empty(),null,null);r.addHeader("Allow","GET, HEAD");return r;}
   if(!file.isFile())return response(event,method,Response.Status.NOT_FOUND,0,0,0,empty(),null,null);
   long size=file.length();String etag="\""+Long.toHexString(size)+"-"+Long.toHexString(file.lastModified())+"\"";
   if(range==null&&etag.equals(session.getHeaders().get("if-none-match")))return response(event,method,Response.Status.NOT_MODIFIED,size,0,0,empty(),etag,null);
   long first=0,last=size-1;boolean partial=method==Method.GET&&range!=null;String ifRange=session.getHeaders().get("if-range");if(partial&&ifRange!=null&&!etag.equals(ifRange))partial=false;
   if(partial){try{String s=range.trim();if(!s.startsWith("bytes=")||s.indexOf(',')>=0)throw new IllegalArgumentException();String[] pair=s.substring(6).split("-",-1);if(pair.length!=2)throw new IllegalArgumentException();if(pair[0].isEmpty()){long suffix=Long.parseLong(pair[1]);if(suffix<=0)throw new IllegalArgumentException();first=Math.max(0,size-suffix);}else{first=Long.parseLong(pair[0]);if(!pair[1].isEmpty())last=Math.min(last,Long.parseLong(pair[1]));}if(size==0||first<0||first>=size||last<first)throw new IllegalArgumentException();}catch(Exception ex){return response(event,method,Response.Status.RANGE_NOT_SATISFIABLE,size,0,0,empty(),etag,"bytes */"+size);}}
   long length=size==0?0:last-first+1;InputStream stream=empty();if(method==Method.GET&&length>0){FileInputStream input=new FileInputStream(file);try{input.getChannel().position(first);stream=new Transfer(input,event,length);}catch(Exception ex){input.close();throw ex;}}
   return response(event,method,partial?Response.Status.PARTIAL_CONTENT:Response.Status.OK,size,first,length,stream,etag,partial?"bytes "+first+"-"+last+"/"+size:null);
  }catch(Exception ex){try{event.row.put("error",ex.getClass().getSimpleName()+": "+ex.getMessage());}catch(JSONException ignored){}return response(event,method,Response.Status.INTERNAL_ERROR,0,0,0,empty(),null,null);}
 }
}
